//#region src/utils/token-identifier.ts
const Bech32mTokenIdentifierTokenIdentifierNetworkPrefix = {
	MAINNET: "btkn",
	REGTEST: "btknrt",
	TESTNET: "btknt",
	SIGNET: "btkns",
	LOCAL: "btknl"
};
function encodeBech32mTokenIdentifier(payload) {
	try {
		const words = bech32m.toWords(payload.tokenIdentifier);
		if (!payload.network) throw new SparkValidationError("Network is required to encode bech32m encoded token identifier", {
			field: "network",
			value: payload.network
		});
		return bech32m.encode(Bech32mTokenIdentifierTokenIdentifierNetworkPrefix[payload.network], words, 500);
	} catch (error) {
		throw new SparkValidationError("Failed to encode bech32m encoded token identifier", {
			field: "tokenIdentifier",
			value: payload.tokenIdentifier,
			error
		});
	}
}
function decodeBech32mTokenIdentifier(bech32mTokenIdentifier, network) {
	try {
		const decoded = bech32m.decode(bech32mTokenIdentifier, 500);
		if (network && decoded.prefix !== Bech32mTokenIdentifierTokenIdentifierNetworkPrefix[network]) throw new SparkValidationError("Invalid bech32m encoded token identifier prefix", {
			field: "bech32mTokenIdentifier",
			value: bech32mTokenIdentifier,
			expected: `prefix='${Bech32mTokenIdentifierTokenIdentifierNetworkPrefix[network]}'`
		});
		return {
			tokenIdentifier: bech32m.fromWords(decoded.words),
			network: network ?? getNetworkFromBech32mTokenIdentifier(bech32mTokenIdentifier)
		};
	} catch (error) {
		if (error instanceof SparkValidationError) throw error;
		throw new SparkValidationError("Failed to decode bech32m encoded token identifier", {
			field: "bech32mTokenIdentifier",
			value: bech32mTokenIdentifier,
			error
		});
	}
}
function getNetworkFromBech32mTokenIdentifier(bech32mTokenIdentifier) {
	const separatorIndex = bech32mTokenIdentifier.indexOf("1");
	if (separatorIndex === -1) throw new SparkValidationError("Invalid bech32m token identifier: no separator found", {
		field: "bech32mTokenIdentifier",
		value: bech32mTokenIdentifier
	});
	const prefix = bech32mTokenIdentifier.slice(0, separatorIndex);
	for (const [network, networkPrefix] of Object.entries(Bech32mTokenIdentifierTokenIdentifierNetworkPrefix)) if (networkPrefix === prefix) return network;
	throw new SparkValidationError("Unknown bech32m token identifier prefix", {
		field: "bech32mTokenIdentifier",
		value: bech32mTokenIdentifier
	});
}

