		const receiverAddress = decodeSparkAddress(receiverSparkAddress, this.config.getNetworkType());
		if (receiverAddress.sparkInvoiceFields) throw new SparkValidationError("Spark address is a Spark invoice. Use fulfillSparkInvoice instead.", {
			field: "receiverSparkAddress",
			value: receiverSparkAddress
		});
