		if (!transfer) throw new Error("Failed to provide preimage");
		const receiverIdentityPublicKey = transfer.receiverIdentityPublicKey;
		if (equalBytes(receiverIdentityPublicKey, await this.config.signer.getIdentityPublicKey())) await this.claimTransfer({
			transfer,
			emit: true
		});
